(2852703, 398532, 32997, '<td valign="top">very clever composition...well done...</td>', 'very clever composition...well done...', '2006-09-20 23:34:00.000000', NULL, 1),
(2852705, 397836, 259, '<td valign="top">a little less busy background would help bring out the model.</td>', 'a little less busy background would help bring out the model.', '2006-09-20 23:34:55.000000', NULL, 1),
