(2854188, 398341, 64928, '<td valign="top">very colorful.</td>', 'very colorful.', '2006-09-21 14:55:22.000000', NULL, 1),
(2854211, 398018, 64928, '<td valign="top">Nice picture, but I don''t think the lines lead to the focal point.  My eyes automatically go to the face and then follow the arms to the flowers...maybe the arms are the leading lines?</td>', 'Nice picture, but I don''t think the lines lead to the focal point.  My eyes automatically go to the face and then follow the arms to the flowers...maybe the arms are the leading lines?', '2006-09-21 15:04:16.000000', NULL, 1),
