(2854518, 395760, 27072, '<td valign="top">A classic, good rendition, well captured.</td>', 'A classic, good rendition, well captured.', '2006-09-21 16:45:29.000000', NULL, 1),
(2854602, 398614, 23921, '<td valign="top">I liked the concept but I see unwanted cars and light near subject head is little off.</td>', 'I liked the concept but I see unwanted cars and light near subject head is little off.', '2006-09-21 17:30:54.000000', NULL, 1),
(2854731, 397373, 64086, '<td valign="top">Nice Photo. I think the background is a bit distracting, maybe a tighter crop.</td>', 'Nice Photo. I think the background is a bit distracting, maybe a tighter crop.', '2006-09-21 18:16:08.000000', NULL, 1),
