(2854881, 397399, 65324, '<td valign="top">The girl is a little out of focus.</td>', 'The girl is a little out of focus.', '2006-09-21 19:25:04.000000', NULL, 1),
(2854891, 398253, 65324, '<td valign="top">I like your title, goes well with your photo.  Good color.</td>', 'I like your title, goes well with your photo.  Good color.', '2006-09-21 19:35:03.000000', NULL, 1),
(2854928, 398324, 61818, '<td valign="top">Interesting effect if not dodge/burn.  Nice composition and smart thinking making the leading lines so painfully obvious that there is no possible way anyone with a full set of chromosones can argue dnmc against you.</td>', 'Interesting effect if not dodge/burn.  Nice composition and smart thinking making the leading lines so painfully obvious that there is no possible way anyone with a full set of chromosones can argue dnmc against you.', '2006-09-21 19:59:39.000000', NULL, 1),
(2854930, 397851, 61818, '<td valign="top">You should submit a larger photo.  This shot is oversharpened.  Not a bad idea but positioning yourself so the railing actually pointed at the ship would have worked a lot better.  Good luck.</td>', 'You should submit a larger photo.  This shot is oversharpened.  Not a bad idea but positioning yourself so the railing actually pointed at the ship would have worked a lot better.  Good luck.', '2006-09-21 20:00:41.000000', NULL, 1),
