(2855963, 397373, 39243, '<td valign="top">great shot but does not meet the challenge. So i give you a 7</td>', 'great shot but does not meet the challenge. So i give you a 7', '2006-09-22 04:15:38.000000', NULL, 1),
(2855966, 397724, 39243, '<td valign="top">I would have liked to see the lines LEAD up to your subject. cool photo none the less.</td>', 'I would have liked to see the lines LEAD up to your subject. cool photo none the less.', '2006-09-22 04:17:40.000000', NULL, 1),
(2855972, 398259, 39243, '<td valign="top">to make this a more effective Leading Lines photo you could try croping the photo just past the person with the umbrella. That way the path leads us to your subject matter.</td>', 'to make this a more effective Leading Lines photo you could try croping the photo just past the person with the umbrella. That way the path leads us to your subject matter.', '2006-09-22 04:21:44.000000', NULL, 1),
(2855979, 398353, 39243, '<td valign="top">the subject is too close for a leading lines shot (in my amature opinion). Try a little distance next time and see how you like it. Good luck.</td>', 'the subject is too close for a leading lines shot (in my amature opinion). Try a little distance next time and see how you like it. Good luck.', '2006-09-22 04:28:26.000000', NULL, 1),
(2856013, 398158, 20950, '<td valign="top">I WANT TO MARRY THIS PICTURE AND HAVE ITS BABIES AND EAT THEM IN THE BOWLS ROTFLMAOOOLRLMOROOROFLMAOROFOLMAOOOOOOOOOOOOOOOAOAOAOAO</td>', 'I WANT TO MARRY THIS PICTURE AND HAVE ITS BABIES AND EAT THEM IN THE BOWLS ROTFLMAOOOLRLMOROOROFLMAOROFOLMAOOOOOOOOOOOOOOOAOAOAOAO', '2006-09-22 05:07:11.000000', NULL, 1),
(2856069, 398409, 64086, '<td valign="top">Very interesting picture, great lighting. My only criticism would be that perhaps the string in the upper left could have been positioned a bit higher or to the left. The way it is positioned now, my eye is drawn to the string itself. It''s also the only string that crosses another.</td>', 'Very interesting picture, great lighting. My only criticism would be that perhaps the string in the upper left could have been positioned a bit higher or to the left. The way it is positioned now, my eye is drawn to the string itself. It''s also the only string that crosses another.', '2006-09-22 06:39:17.000000', NULL, 1),
(2856074, 398446, 23430, '<td valign="top">Cool shot. B &amp; W works well here.</td>', 'Cool shot. B & W works well here.', '2006-09-22 06:41:48.000000', NULL, 1),
(2856075, 397221, 27524, '<td valign="top">Creative angle and composition. Interesting light just on right side.</td>', 'Creative angle and composition. Interesting light just on right side.', '2006-09-22 06:41:58.000000', NULL, 1),
(2856078, 398347, 27524, '<td valign="top">Its very intesresting photo... sheeps in foreground and fences leading to other sheeps in background and then the landscape too. I think there is enough subject to take three pictures :). Maybe bit too busy but nice done.</td>', 'Its very intesresting photo... sheeps in foreground and fences leading to other sheeps in background and then the landscape too. I think there is enough subject to take three pictures :). Maybe bit too busy but nice done.', '2006-09-22 06:44:20.000000', NULL, 1),
(2856079, 396378, 27524, '<td valign="top">Simple and tasteful architecture photo...nice choice of angle.</td>', 'Simple and tasteful architecture photo...nice choice of angle.', '2006-09-22 06:44:52.000000', NULL, 1),
(2856080, 396294, 27524, '<td valign="top">Lovely color and curve of leaf... maybe bit feeling too tight cropped.</td>', 'Lovely color and curve of leaf... maybe bit feeling too tight cropped.', '2006-09-22 06:45:45.000000', NULL, 1),
