(2858119, 396797, 39702, '<td valign="top">Short DOF is distracting. Also a little out of focus.</td>', 'Short DOF is distracting. Also a little out of focus.', '2006-09-23 01:59:53.000000', NULL, 1),
(2858137, 396793, 39702, '<td valign="top">A bit fuzzy.</td>', 'A bit fuzzy.', '2006-09-23 02:12:31.000000', NULL, 1),
