(2863022, 398452, 65522, '<td valign="top">This is a great picture.  The yellowish-green really contrasts well with the dark grate (I suppose that''s what it is).</td>', 'This is a great picture.  The yellowish-green really contrasts well with the dark grate (I suppose that''s what it is).', '2006-09-25 11:47:15.000000', NULL, 1),
(2863023, 396133, 64035, '<td valign="top">Nice interpretation of the challenge. I find the bedspread annoying and distracting. Cute model, though. Also, the light on her side is a flaw.</td>', 'Nice interpretation of the challenge. I find the bedspread annoying and distracting. Cute model, though. Also, the light on her side is a flaw.', '2006-09-25 11:47:33.000000', NULL, 1),
