(2863029, 396817, 64035, '<td valign="top">Nice photograph, and the water looks absolutely gorgeous. Am uncertain about the angle, though. I don''t know that a more standard photograph wouldn''t be as interesting. Feels a little like you''re trying too hard.</td>', 'Nice photograph, and the water looks absolutely gorgeous. Am uncertain about the angle, though. I don''t know that a more standard photograph wouldn''t be as interesting. Feels a little like you''re trying too hard.', '2006-09-25 11:48:53.000000', NULL, 1),
(2863030, 398384, 64035, '<td valign="top">Gorgeous sky. Great colours on the fence. Very very impressive.</td>', 'Gorgeous sky. Great colours on the fence. Very very impressive.', '2006-09-25 11:49:30.000000', NULL, 1),
(2863032, 398607, 64035, '<td valign="top">Nice tones, and an interesting image. Well done.</td>', 'Nice tones, and an interesting image. Well done.', '2006-09-25 11:49:50.000000', NULL, 1),
(2863036, 398148, 64035, '<td valign="top">I love the mist over the treas at the back, and the stillness of the water is lovely. Slightly more contrast in the image might have made it a little more striking.</td>', 'I love the mist over the treas at the back, and the stillness of the water is lovely. Slightly more contrast in the image might have made it a little more striking.', '2006-09-25 11:51:11.000000', NULL, 1),
