(2865343, 397151, 46832, '<td valign="top">Where do I begin?<br/> - way too small...<br/> - out of focus...<br/> - can''t tell what''s going on...<br/> - doesn''t appear to meet the challenge...</td>', 'Where do I begin? - way too small... - out of focus... - can''t tell what''s going on... - doesn''t appear to meet the challenge...', '2006-09-26 05:56:37.000000', NULL, 1),
(2865347, 396797, 46832, '<td valign="top">Good use of leading line but the lines should lead to the subject.  Being out of focus, the subject is hard for me to look at.  Girl should be in focus with leading line soft at right edge.</td>', 'Good use of leading line but the lines should lead to the subject.  Being out of focus, the subject is hard for me to look at.  Girl should be in focus with leading line soft at right edge.', '2006-09-26 06:03:21.000000', NULL, 1),
(2865395, 398351, 64035, '<td valign="top">Difficult to get to shoot this bridge when there''s no-one on it, I know, but the people clutter up this image and distract from the lines of the bridge. It''s a nicely taken photo, though.</td>', 'Difficult to get to shoot this bridge when there''s no-one on it, I know, but the people clutter up this image and distract from the lines of the bridge. It''s a nicely taken photo, though.', '2006-09-26 07:08:46.000000', NULL, 1),
(2865397, 397838, 64035, '<td valign="top">Groovy looking spider, and the web''s great, but the background takes away a lot of impact from the image.</td>', 'Groovy looking spider, and the web''s great, but the background takes away a lot of impact from the image.', '2006-09-26 07:09:29.000000', NULL, 1),
(2865399, 398238, 64035, '<td valign="top">Nice pure interpretation of the challenge. I like the column to the right, but I think cropping away the stuff in the bottom left hand corner would be a better choice.</td>', 'Nice pure interpretation of the challenge. I like the column to the right, but I think cropping away the stuff in the bottom left hand corner would be a better choice.', '2006-09-26 07:10:24.000000', NULL, 1),
(2865402, 398435, 64035, '<td valign="top">Shooting this image against the light rather than with it might have been better. The lines get lost against the sky, and the sky itself just isn''t that interesting.</td>', 'Shooting this image against the light rather than with it might have been better. The lines get lost against the sky, and the sky itself just isn''t that interesting.', '2006-09-26 07:11:25.000000', NULL, 1),
(2865403, 397632, 64035, '<td valign="top">I like the texture on the chocolate - you''ve really captured the velvety surface well. Good idea, good image.</td>', 'I like the texture on the chocolate - you''ve really captured the velvety surface well. Good idea, good image.', '2006-09-26 07:12:05.000000', NULL, 1),
(2865405, 398420, 64035, '<td valign="top">Nice idea, lovely flowers. The overall image is too clutter for my taste - there are too many flowers!</td>', 'Nice idea, lovely flowers. The overall image is too clutter for my taste - there are too many flowers!', '2006-09-26 07:12:49.000000', NULL, 1),
(2865411, 398324, 64035, '<td valign="top">Very clever idea. It would be better, in my opinion, if the egg was just a little punchier and stood out from the backgroud more.</td>', 'Very clever idea. It would be better, in my opinion, if the egg was just a little punchier and stood out from the backgroud more.', '2006-09-26 07:14:27.000000', NULL, 1),
(2865414, 396444, 64035, '<td valign="top">Great image. Love the colour and the texture. Really hits the eye hard.</td>', 'Great image. Love the colour and the texture. Really hits the eye hard.', '2006-09-26 07:15:47.000000', NULL, 1),
(2865416, 396763, 64035, '<td valign="top">Great opportunism and eye, but the overall image is a bit dreary and dark.</td>', 'Great opportunism and eye, but the overall image is a bit dreary and dark.', '2006-09-26 07:17:23.000000', NULL, 1),
