(2865434, 396986, 62812, '<td valign="top">great atmosphere</td>', 'great atmosphere', '2006-09-26 07:50:50.000000', NULL, 1),
(2865436, 397938, 62812, '<td valign="top">tenuous</td>', 'tenuous', '2006-09-26 07:52:04.000000', NULL, 1),
(2865468, 396389, 65779, '<td valign="top">Great depth of field and I like the yellow line round the field.</td>', 'Great depth of field and I like the yellow line round the field.', '2006-09-26 08:20:51.000000', NULL, 1),
(2865469, 398062, 65779, '<td valign="top">I like the interpretation of the theme.</td>', 'I like the interpretation of the theme.', '2006-09-26 08:22:06.000000', NULL, 1),
(2865475, 398376, 65779, '<td valign="top">Great as the railings lead the eye in a circle to the lighthouse and then round to the rainbow.  Very pretty.</td>', 'Great as the railings lead the eye in a circle to the lighthouse and then round to the rainbow.  Very pretty.', '2006-09-26 08:23:34.000000', NULL, 1),
(2865477, 396986, 65779, '<td valign="top">Lovely depth of field and colours</td>', 'Lovely depth of field and colours', '2006-09-26 08:24:18.000000', NULL, 1),
(2865479, 398502, 65779, '<td valign="top">I don''t see the lines here</td>', 'I don''t see the lines here', '2006-09-26 08:24:40.000000', NULL, 1),
(2865482, 396051, 65779, '<td valign="top">Lighting could be improved as could composition.</td>', 'Lighting could be improved as could composition.', '2006-09-26 08:27:04.000000', NULL, 1),
(2865484, 397666, 65779, '<td valign="top">A strange way to start a marriage.  Mixed metaphors like this don''t work for me.</td>', 'A strange way to start a marriage.  Mixed metaphors like this don''t work for me.', '2006-09-26 08:27:54.000000', NULL, 1),
(2865485, 398532, 65779, '<td valign="top">Colour gives an olde world feel.  Thanks.</td>', 'Colour gives an olde world feel.  Thanks.', '2006-09-26 08:29:01.000000', NULL, 1),
(2865487, 398614, 65779, '<td valign="top">Very interesting one.</td>', 'Very interesting one.', '2006-09-26 08:29:39.000000', NULL, 1),
(2865488, 398347, 65779, '<td valign="top">I like the way the sheep are not the subject of this - rather the graphic shapes made by the fences.</td>', 'I like the way the sheep are not the subject of this - rather the graphic shapes made by the fences.', '2006-09-26 08:30:42.000000', NULL, 1),
(2865489, 397847, 65779, '<td valign="top">Lines don''t lead here...</td>', 'Lines don''t lead here...', '2006-09-26 08:31:35.000000', NULL, 1),
(2865491, 398384, 65779, '<td valign="top">Dynamic feel to this - great.</td>', 'Dynamic feel to this - great.', '2006-09-26 08:33:29.000000', NULL, 1),
(2865493, 398243, 65779, '<td valign="top">Too blurred to work well.</td>', 'Too blurred to work well.', '2006-09-26 08:34:15.000000', NULL, 1),
(2865494, 398435, 65779, '<td valign="top">Bit boring.</td>', 'Bit boring.', '2006-09-26 08:34:52.000000', NULL, 1),
(2865498, 396797, 65779, '<td valign="top">Focus is faulty unfortunately</td>', 'Focus is faulty unfortunately', '2006-09-26 08:37:08.000000', NULL, 1),
(2865500, 397223, 65779, '<td valign="top">I would have gone closer to the water and included more beach to give more balance</td>', 'I would have gone closer to the water and included more beach to give more balance', '2006-09-26 08:39:03.000000', NULL, 1),
(2865503, 395559, 64035, '<td valign="top">Nice capture of the grain on the wood. Interestingly, perhaps the most pleasing line is the curve on the top of the soundbox. The brightspot in the bottom right hand corner is a bit of a blemish.</td>', 'Nice capture of the grain on the wood. Interestingly, perhaps the most pleasing line is the curve on the top of the soundbox. The brightspot in the bottom right hand corner is a bit of a blemish.', '2006-09-26 08:41:59.000000', NULL, 1),
(2865504, 398518, 65779, '<td valign="top">Nice one.  I like the flowers out of focus.</td>', 'Nice one.  I like the flowers out of focus.', '2006-09-26 08:42:18.000000', NULL, 1),
(2865507, 398607, 65779, '<td valign="top">Confused lines with no real subject.</td>', 'Confused lines with no real subject.', '2006-09-26 08:42:57.000000', NULL, 1),
(2865509, 398410, 64035, '<td valign="top">Good photo. Couple of points - I found the angle that the surface is (or appears to be) at slightly unattractive. Also, because of the direction the subject is looking, the lines of the surface moved my gaze away from him, not towards. Which is different, but not altogether pleasing.</td>', 'Good photo. Couple of points - I found the angle that the surface is (or appears to be) at slightly unattractive. Also, because of the direction the subject is looking, the lines of the surface moved my gaze away from him, not towards. Which is different, but not altogether pleasing.', '2006-09-26 08:43:52.000000', NULL, 1),
(2865510, 396905, 65779, '<td valign="top">Lovely sharp shot with good saturation.</td>', 'Lovely sharp shot with good saturation.', '2006-09-26 08:44:40.000000', NULL, 1),
(2865511, 396136, 64035, '<td valign="top">Perhaps a bit stock and unoriginal, but well taken. It''s a good choice to have the middle bottles in focus, rather than the near ones. Nice colours, too.</td>', 'Perhaps a bit stock and unoriginal, but well taken. It''s a good choice to have the middle bottles in focus, rather than the near ones. Nice colours, too.', '2006-09-26 08:44:41.000000', NULL, 1),
(2865513, 398429, 64035, '<td valign="top">Excellent. To make it *perfect*, a little more light coming from whatever is at the end of the image. But the curve and the lights across it are lovely.</td>', 'Excellent. To make it *perfect*, a little more light coming from whatever is at the end of the image. But the curve and the lights across it are lovely.', '2006-09-26 08:45:38.000000', NULL, 1),
(2865514, 398429, 65779, '<td valign="top">This is simple but works well.</td>', 'This is simple but works well.', '2006-09-26 08:45:40.000000', NULL, 1),
(2865516, 398475, 64035, '<td valign="top">Inventive interpretation of the challenge. The image feels washed, though, and a little uninteresting as a result.</td>', 'Inventive interpretation of the challenge. The image feels washed, though, and a little uninteresting as a result.', '2006-09-26 08:46:18.000000', NULL, 1),
(2865518, 397683, 65779, '<td valign="top">Lines don''t really lead to the subject.</td>', 'Lines don''t really lead to the subject.', '2006-09-26 08:47:14.000000', NULL, 1),
(2865521, 396294, 64035, '<td valign="top">Great colours on this, and the quality on the tip of the leaf is gorgeous. The more I look at this, the more I like it.</td>', 'Great colours on this, and the quality on the tip of the leaf is gorgeous. The more I look at this, the more I like it.', '2006-09-26 08:48:03.000000', NULL, 1),
(2865523, 397724, 64035, '<td valign="top">Nice image. The focus looks a little off on her face, which is disappointing in a picture like this. Good tone otherwise.</td>', 'Nice image. The focus looks a little off on her face, which is disappointing in a picture like this. Good tone otherwise.', '2006-09-26 08:49:18.000000', NULL, 1),
(2865524, 398518, 64035, '<td valign="top">Very nice image. Lovely variation in the greens, and good contrast with the pinks.</td>', 'Very nice image. Lovely variation in the greens, and good contrast with the pinks.', '2006-09-26 08:49:58.000000', NULL, 1),
(2865631, 398018, 32581, '<td valign="top">good one.</td>', 'good one.', '2006-09-26 10:18:10.000000', NULL, 1),
